INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 9, 'theory', 'Quiz: DDL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 0, 'What happens on an INSERT without a value for an INTEGER PRIMARY KEY column in SQLite?', '["An error: the key is required", "The database assigns the next number itself", "NULL is inserted", "0 is inserted"]', 1, 'INTEGER PRIMARY KEY is an alias for the internal rowid; if no value is given, the next free number is used.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 1, 'How does UNIQUE differ from PRIMARY KEY?', '["It does not", "A UNIQUE column allows NULL (and, by the standard, several of them)", "UNIQUE forbids gaps, PRIMARY KEY does not", "UNIQUE cannot be used with text"]', 1, 'A primary key does not allow NULL and there is only one per table. There can be several UNIQUE columns, and gaps in them are allowed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 2, 'What is CHECK (price >= 0) for?', '["Speeds up search by price", "Rejects inserts and updates that violate the condition", "Sorts prices", "Replaces the price with zero"]', 1, 'CHECK is a per-row rule: if the condition is violated, the command fails with an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 3, 'What does ON DELETE CASCADE do in a foreign key?', '["Forbids deleting the parent", "Deletes dependent rows along with the parent row", "Clears the reference", "Nothing: it is a comment"]', 1, 'CASCADE deletes the rows that refer to the one being deleted; SET NULL clears the reference, RESTRICT forbids the deletion.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 4, 'Why write CREATE TABLE IF NOT EXISTS?', '["So the table is created faster", "So the script can be run again without an error", "To delete the old table", "To add an index"]', 1, 'The IF NOT EXISTS clause makes the command idempotent: if the table already exists, nothing happens and there is no error.');
